insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('BS', 'default', 'The Bahamas reference chart of accounts', '{}'::jsonb, true, 'companies', array['BS-IFRS-IS', 'BS-IFRS-SFP']::text[], null, 'There is no statutory chart of accounts in The Bahamas in the texts consulted. The Value Added Tax Act, 2014, requires a registrant to account for output tax, input tax and the net amount payable for each tax period (ss. 46 and 47) and to hold the invoice, credit note or import declaration behind every input tax claim (s. 50(1)(d) and (e)). This chart is original: four digits, blocked so that each range reaches one line of the IFRS-style statements, with the accounts a Bahamian company keeps — a Bahamian dollar current account and a foreign currency account, VAT output and input tax, the net VAT settlement account, VAT collected by Customs on imports, VAT withheld under section 23A, and National Insurance. The Bahamas has no income tax on companies or individuals: the accounts for income taxes are for taxes paid abroad and for the domestic minimum top-up tax of large multinational groups.', 'vat-act')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

