insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('BS', 'BS-VAT', 'VAT return', array['month', 'quarter']::declaration_period[], null, date '2015-01-01', null, 'Value Added Tax Act, 2014, s. 46(2) and s. 47 — the tax period of a registrant is one calendar month or another period the Comptroller determines in a particular case (the Department''s guidance on filing a quarterly return shows quarterly filing for smaller registrants), and the registrant files a VAT return in the prescribed form for each period whether or not tax is payable. The form is filed online at vat.revenue.gov.bs. The boxes carry the line numbers of the Department''s guidance on completing the return (standard method, version of 1 January 2017), and the lines for the reduced rate are the pack''s own; the pack carries the lines a document writes into and the totals between them (1, 2, 4 to 5, 7 to 10, 12, 14, 18, 19 and 25 to 27). Withholding (Forms 73 and 74), the bonded supplies, the reverse charge on imported services (lines 6 and 16), the deferred import VAT, the credit brought forward and the fines are not carried: see the README.', true,'day_of_month_after_period'::filing_deadline_rule, 21, null, 'Value Added Tax Act, 2014, s. 47(1)(a) and (b) — the return is filed, and the tax paid, within twenty-one days after the end of the tax period; the Department''s payment page repeats it. A large taxpayer has fourteen days (s. 47(1A)), which this deadline does not carry: it depends on a fact about the company. The Act does not move a date that falls on a weekend or a holiday.', 'vat-payment-page', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('BS', 'BS-VAT', '1', 'base', 'Line 1 — Zero-rated supplies', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 1: the total of zero-rated sales made during the period.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '2', 'base', 'Line 2 — Exempt supplies', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 2: the total of exempt sales made during the period.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '4', 'base', 'Line 4 — Taxable supplies at the standard rate (10 %), value without VAT', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 4: the standard-rated sales. The guide prints the value inclusive of VAT; this box holds the value without tax and box 4I adds the tax back.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '5', 'tax', 'Line 5 — VAT collected on standard-rate supplies', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 5 = line 4 × (rate / (100 + rate)): 10/110 at 10 % (the guide, from 2017, prints 7.5/107.5).', 'vat-guide-return'),
  ('BS', 'BS-VAT', '4I', 'total', 'Line 4 as printed — standard-rated supplies, VAT included', '{}'::jsonb, 50, null, array['4', '5']::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 4, inclusive of the VAT charged, as the form prints it.', 'vat-guide-return'),
  ('BS', 'BS-VAT', 'R4', 'base', 'Reduced rate (5 %) — Taxable supplies, value without VAT', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax (Amendment) Act, 2025, s. 3 — the reduced rate of five per cent from 1 April 2025. The guide (2017) and the worksheet online predate it and have no line for it: this box is the pack''s own and the preparer places it on the current form.', 'vat-amend-2025'),
  ('BS', 'BS-VAT', 'R5', 'tax', 'Reduced rate (5 %) — VAT collected on reduced-rated supplies', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'As box R4: the VAT at the reduced rate of five per cent.', 'vat-amend-2025'),
  ('BS', 'BS-VAT', '7', 'tax', 'Line 7 — Output adjustments for the period', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 7: debit notes issued, credit notes received and bad debts relating to supplies reported in a previous period — declared and empty: a credit note issued in the period is written into lines 4 and 5 by the document itself, so the line stays for the adjustments the preparer enters by hand.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '8', 'total', 'Line 8 — Supplies excluding VAT, taxable and bonded', '{}'::jsonb, 90, null, array['1', '4', 'R4']::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 8 = L1 + L3 + L4 − L5: the zero-rated and standard-rated sales without VAT (bonded supplies, line 3, are not carried). The reduced-rate supplies, which the guide does not know, are added here.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '9', 'total', 'Line 9 — Total supplies excluding VAT', '{}'::jsonb, 100, null, array['2', '8']::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 9 = L2 + L8: the exempt supplies and the line 8 total.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '10', 'total', 'Line 10 — Total output tax', '{}'::jsonb, 110, null, array['5', 'R5', '7']::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 10 = L5 + L6 + L7. Line 6, the reverse charge on imported services, is not carried; the VAT at the reduced rate (R5) is added.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '12', 'base', 'Lines 12 and 13 — Value of imports (capital goods and operating inputs), without VAT', '{}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, lines 12 and 13: the value of imports of capital goods and services, and of operating inputs, exclusive of VAT. The guide splits them in two; this box holds both.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '14', 'tax', 'Line 14 — VAT paid on imported goods', '{}'::jsonb, 130, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 14: the VAT paid at the border on imported goods. Line 15, the import VAT deferred, is not carried.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '18', 'base', 'Lines 17 and 18 — Value of domestic purchases (capital and operating), without VAT', '{}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, lines 17 and 18: the value of domestic purchases of capital goods and services, and of operating inputs, exclusive of VAT, whether standard-rated, reduced-rated, zero-rated or exempt. The guide splits them in two; this box holds both.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '19', 'tax', 'Line 19 — VAT paid on domestic goods and services', '{}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 19: the VAT paid on domestic goods and services, and the deemed VAT.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '25', 'tax', 'Line 25 — Input adjustments for the period', '{}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 25: credit notes issued and debit notes received for purchases reported in a previous period — declared and empty, for the reason given at line 7.', 'vat-guide-return'),
  ('BS', 'BS-VAT', '26', 'total', 'Line 26 — Total input tax', '{}'::jsonb, 170, null, array['14', '19', '25']::text[], '{}'::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 26 = L23 + L24 + L25, the claimable input tax. The guide splits L20 into the part attributable to taxable supplies, the part from mixed supplies (apportionment worksheet) and the part not claimable (lines 21 to 24); the pack claims the whole of the tax entered on lines 14 and 19 (line 16, the reverse charge on imported services, is not carried).', 'vat-guide-return'),
  ('BS', 'BS-VAT', '27', 'total', 'Line 27 — VAT payable (positive) or VAT credit (negative)', '{}'::jsonb, 180, null, array['10']::text[], array['26']::text[], null, null, false, false, null, 'VAT Guidance on Completing a VAT Return, line 27 = L10 − L26, which can be negative. Lines 28 to 31 (deferred VAT, the credit brought forward and the net amount) settle one period against the next and are not documents.', 'vat-guide-return')
