update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value Added Tax Act, 2014, s. 54(1) and (3)(a) — a registrant supplier issues to a registrant recipient an original VAT invoice within sixty calendar days, in the form and with the particulars the Comptroller prescribes, and only one VAT invoice for a taxable supply; a copy is marked "copy" (s. 54(4)). The Act asks for one invoice per supply and not for a series without gaps, which is why the style is `sequential`. The particulars the Comptroller prescribes are in the VAT Rules on the content of invoices and receipts, which were not read.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_date',
  tax_point_legal_reference     = 'The time of supply is section 32 of the Act (rules relating to time of supply), which was not read for this pack. `invoice_date` is declared as a convention of this pack and not as a rule of the law; a payment or a deposit received before the invoice may bring the supply forward, and is recorded as a gap in the README.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'None of the texts consulted (the VAT Act and its amendments to 2025, the Department''s guidance on invoices, sales receipts, credit notes and debit notes, its payment page) imposes a structured electronic invoice or a clearance system: a VAT invoice is a document with prescribed particulars (s. 54) and the return is filed online. No Peppol authority or published profile was found, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`.',
  einvoice_source_key           = 'vat-act',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
